#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda_bf16.h>
#include <cuda_runtime.h>
#include <mma.h>
namespace {
using namespace nvcuda;
constexpr int IN_C = 3;
constexpr int OUT_C = 32;
constexpr int K = 3;
constexpr int K_ELEMS = IN_C * K * K;  // 27
constexpr int K_PAD = 32;             // reduction padded to multiple of 16
constexpr int NTILE = 256;            // output spatial positions per block (doubled tile: halves per-tile weight/halo overhead and, with 512 threads x 3 blocks/SM, raises theoretical occupancy to 100% for better DRAM store overlap)
constexpr int B_LD = NTILE + 8;       // padded smem B row stride (skew), multiple of 8 elems (16B) to keep WMMA alignment while breaking 256B row-stride bank conflicts
constexpr int THREADS = 512;
constexpr int WM = 16;
constexpr int WN = 16;
constexpr int WK = 16;
constexpr int SMEM_BYTES = OUT_C * NTILE * (int)sizeof(float);  // 32 KB
// Implicit-GEMM 3x3 convolution using bf16 tensor-core WMMA.
// GEMM view: C[oc][s] = sum_k W[oc][k] * im2col(X)[k][s],
//   M = 32 output channels, N = Ho*Wo spatial per image, K = 27 (padded to 32).
__global__ void __launch_bounds__(THREADS, 3) conv3x3_bf16_kernel(
    const __nv_bfloat16* __restrict__ x,
    const __nv_bfloat16* __restrict__ w,
    __nv_bfloat16* __restrict__ y,
    const int N,
    const int H,
    const int W,
    const int Ho,
    const int Wo,
    const int use_halo) {
  extern __shared__ __align__(16) unsigned char smem_raw[];
  __nv_bfloat16* sA = reinterpret_cast<__nv_bfloat16*>(smem_raw);  // [32][32]
  __nv_bfloat16* sB = reinterpret_cast<__nv_bfloat16*>(
      smem_raw + OUT_C * K_PAD * sizeof(__nv_bfloat16));           // [32][NTILE]
  __nv_bfloat16* sX = reinterpret_cast<__nv_bfloat16*>(
      smem_raw + (OUT_C * K_PAD + K_PAD * B_LD) * (int)sizeof(__nv_bfloat16));  // input halo tile [IN_C][rows][W]
  float* sC = reinterpret_cast<float*>(smem_raw);                  // reused, [32][NTILE]
  const int tid = threadIdx.x;
  const int n = blockIdx.y;
  const int s0 = blockIdx.x * NTILE;
  const int S = Ho * Wo;
  // Input-halo staging (shared-memory reuse optimization): each block
  // fetches its input halo tile from global memory exactly once into
  // shared memory, then builds the im2col B tile from shared memory.
  // This removes the ~9x redundant global loads of the 3x3 sliding
  // window, cutting DRAM read traffic and LSU pressure for this
  // DRAM-bound kernel. The halo rows per channel are contiguous in
  // global memory, so the staging loop is fully coalesced.
  const int s_hi = min(s0 + NTILE - 1, S - 1);
  const int row_lo = s0 / Wo;              // == oh_lo
  const int oh_hi = s_hi / Wo;
  int rows = oh_hi + K - row_lo;           // input rows this tile needs
  const int max_rows = H - row_lo;
  if (rows > max_rows) {
    rows = max_rows;
  }
  if (use_halo) {
    const int halo_len = rows * W;         // per-channel halo elements
    const int total = IN_C * halo_len;
    const __nv_bfloat16* xh = x + (size_t)n * IN_C * H * W + (size_t)row_lo * W;
    for (int idx = tid; idx < total; idx += THREADS) {
      const int c = idx / halo_len;
      const int r = idx - c * halo_len;
      sX[idx] = __ldg(&xh[(size_t)c * H * W + r]);
    }
    __syncthreads();
  }
  // Cooperative staging: all 512 threads participate in the global->shared
  // staging phase instead of leaving half the block idle. Each thread owns
  // one spatial column (tid & 255) and one ky-group (tid >> 8): group 0
  // stages the ky=0 im2col rows plus the K_PAD zero fill, group 1 stages
  // the ky=1,2 rows. Weight staging (matrix A) is folded into group 0 so
  // it overlaps with group 1's im2col loads rather than serializing ahead
  // of the B staging, shortening the staging critical path before the MMA.
  {
    const int sl = tid & (NTILE - 1);
    const int kg = tid >> 8;  // ky-group: 0 -> ky=0, 1 -> ky=1..2
    const int s = s0 + sl;
    const bool s_valid = (s < S);
    int oh = 0;
    int ow = 0;
    if (s_valid) {
      oh = s / Wo;
      ow = s - oh * Wo;
    }
    const __nv_bfloat16* xn = x + (size_t)n * IN_C * H * W;
