  auto w_c = w.contiguous();
  const int64_t N = x_c.size(0);
  const int64_t H = x_c.size(2);
  const int64_t W = x_c.size(3);
  TORCH_CHECK(H >= 3 && W >= 3, "spatial size must be >= 3");
  const int64_t Ho = H - 2;
  const int64_t Wo = W - 2;
  auto y = torch::empty({N, 32, Ho, Wo}, x_c.options());
  if (N == 0 || Ho == 0 || Wo == 0) {
    return y;
  }
  const int64_t S = Ho * Wo;
  dim3 block(THREADS, 1, 1);
  dim3 grid((unsigned)((S + NTILE - 1) / NTILE), (unsigned)N, 1);
  // Halo-tile shared-memory sizing: dynamic smem layout is sA | sB | sX.
  // sC accumulator reuse still needs at least SMEM_BYTES (32 KB).
  int rows_worst = (int)((NTILE - 1) / Wo) + K;
  if (rows_worst > (int)H) {
    rows_worst = (int)H;
  }
  const size_t halo_bytes =
      ((size_t)IN_C * rows_worst * W * sizeof(__nv_bfloat16) + 15) & ~(size_t)15;
  const size_t ab_bytes =
      (size_t)(OUT_C * K_PAD + K_PAD * B_LD) * sizeof(__nv_bfloat16);
  size_t smem_bytes = ab_bytes + halo_bytes;
  if (smem_bytes < SMEM_BYTES) {
    smem_bytes = SMEM_BYTES;
  }
  int use_halo = 1;
  int dev = 0;
  C10_CUDA_CHECK(cudaGetDevice(&dev));
  static int max_optin[64] = {0};
  if (max_optin[dev] == 0) {
    cudaDeviceProp prop;
    C10_CUDA_CHECK(cudaGetDeviceProperties(&prop, dev));
    max_optin[dev] = (int)prop.sharedMemPerBlockOptin;
  }
  if (smem_bytes > (size_t)max_optin[dev]) {
    use_halo = 0;  // extreme shapes: fall back to direct __ldg staging
    smem_bytes = SMEM_BYTES;
  } else if (smem_bytes > 48 * 1024) {
    C10_CUDA_CHECK(cudaFuncSetAttribute(
        conv3x3_bf16_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize,
        (int)smem_bytes));
  }
  const __nv_bfloat16* x_ptr =
      reinterpret_cast<const __nv_bfloat16*>(x_c.data_ptr<at::BFloat16>());
  const __nv_bfloat16* w_ptr =
      reinterpret_cast<const __nv_bfloat16*>(w_c.data_ptr<at::BFloat16>());
  __nv_bfloat16* y_ptr =
      reinterpret_cast<__nv_bfloat16*>(y.data_ptr<at::BFloat16>());
  conv3x3_bf16_kernel<<<grid, block, smem_bytes, at::cuda::getCurrentCUDAStream()>>>(
      x_ptr, w_ptr, y_ptr, (int)N, (int)H, (int)W, (int)Ho, (int)Wo, use_halo);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
  return y;
}
