        sB[k * B_LD + sl] = __float2bfloat16(0.0f);
      }
      // Stage weights [32][27] into padded [32][32] shared tile (matrix A).
      #pragma unroll
      for (int j = 0; j < 4; ++j) {
        const int idx = j * 256 + sl;
        const int oc = idx >> 5;
        const int k = idx & 31;
        __nv_bfloat16 v = __float2bfloat16(0.0f);
        if (k < K_ELEMS) {
          v = __ldg(&w[(size_t)oc * K_ELEMS + k]);
        }
        sA[idx] = v;
      }
    } else {
      #pragma unroll
      for (int c = 0; c < IN_C; ++c) {
        #pragma unroll
        for (int ky = 1; ky < K; ++ky) {
          const int ih = oh + ky;
          #pragma unroll
          for (int kx = 0; kx < K; ++kx) {
            __nv_bfloat16 v = __float2bfloat16(0.0f);
            if (s_valid) {
              v = use_halo ? sX[(c * rows + (ih - row_lo)) * W + (ow + kx)]
                           : __ldg(&xn[((size_t)c * H + ih) * W + (ow + kx)]);
            }
            sB[(c * 9 + ky * 3 + kx) * B_LD + sl] = v;
          }
        }
      }
    }
  }
  __syncthreads();
  // 16 warps: 2 rows of 16 output channels x 8 slabs of 32 spatial positions.
  const int warp = tid >> 5;
  const int warp_m = warp & 1;
  const int warp_n = warp >> 1;
  const int oc0 = warp_m * WM;
  const int sn0 = warp_n * 32;
  wmma::fragment<wmma::accumulator, WM, WN, WK, float> acc[2];
  #pragma unroll
  for (int i = 0; i < 2; ++i) {
    wmma::fill_fragment(acc[i], 0.0f);
  }
  #pragma unroll
  for (int kt = 0; kt < K_PAD / WK; ++kt) {
    wmma::fragment<wmma::matrix_a, WM, WN, WK, __nv_bfloat16, wmma::row_major> afrag;
    wmma::load_matrix_sync(afrag, sA + oc0 * K_PAD + kt * WK, K_PAD);
    #pragma unroll
    for (int nf = 0; nf < 2; ++nf) {
      wmma::fragment<wmma::matrix_b, WM, WN, WK, __nv_bfloat16, wmma::row_major> bfrag;
      wmma::load_matrix_sync(bfrag, sB + (kt * WK) * B_LD + sn0 + nf * WN, B_LD);
      wmma::mma_sync(acc[nf], afrag, bfrag, acc[nf]);
    }
  }
  __syncthreads();
  // Stage accumulators (f32) into shared memory, reusing the A/B buffer.
  #pragma unroll
  for (int nf = 0; nf < 2; ++nf) {
    wmma::store_matrix_sync(sC + oc0 * NTILE + sn0 + nf * WN, acc[nf], NTILE,
                            wmma::mem_row_major);
  }
  __syncthreads();
  // Convert to bf16 and write out. Each thread packs two adjacent spatial
  // positions into one 32-bit streaming store (st.global.cs): warp stores
  // are 128-byte coalesced and marked evict-first so the large output
  // tensor does not thrash the much smaller input tensor in L2, reducing
  // total DRAM traffic for this DRAM-bound kernel.
  {
    const int half = tid >> 8;            // 0 -> oc 0..15, 1 -> oc 16..31
    const int pair = tid & 127;           // spatial pair index (0..127)
    const int grp = (tid >> 7) & 1;       // 0 -> oc +0..7, 1 -> oc +8..15
    const int sp = s0 + 2 * pair;         // first spatial position of the pair
    if (((S & 1) == 0) && (sp + 1 < S)) {
      // S even: every packed address is 4-byte aligned; all pairs full.
      __nv_bfloat16* yn = y + (size_t)n * OUT_C * S + sp;
      const float2* sCp = reinterpret_cast<const float2*>(sC + 2 * pair);
      #pragma unroll
      for (int i = 0; i < 8; ++i) {
        const int oc = half * 16 + grp * 8 + i;
        const float2 f2 = sCp[oc * (NTILE / 2)];
        const __nv_bfloat16 b0 = __float2bfloat16(f2.x);
        const __nv_bfloat16 b1 = __float2bfloat16(f2.y);
        const unsigned int packed =
            ((unsigned int)*reinterpret_cast<const unsigned short*>(&b1) << 16) |
            (unsigned int)*reinterpret_cast<const unsigned short*>(&b0);
        __stcs(reinterpret_cast<unsigned int*>(yn + (size_t)oc * S), packed);
      }
    } else if (sp < S) {
      // Odd-S fallback / ragged tail: scalar 16-bit streaming stores.
      __nv_bfloat16* yn = y + (size_t)n * OUT_C * S + sp;
      #pragma unroll
      for (int i = 0; i < 8; ++i) {
        const int oc = half * 16 + grp * 8 + i;
        const __nv_bfloat16 b0 = __float2bfloat16(sC[oc * NTILE + 2 * pair]);
        __stcs(reinterpret_cast<unsigned short*>(yn + (size_t)oc * S),
               *reinterpret_cast<const unsigned short*>(&b0));
        if (sp + 1 < S) {
          const __nv_bfloat16 b1 = __float2bfloat16(sC[oc * NTILE + 2 * pair + 1]);
          __stcs(reinterpret_cast<unsigned short*>(yn + (size_t)oc * S + 1),
                 *reinterpret_cast<const unsigned short*>(&b1));
        }
      }
    }
  }
}
